diff --git a/libarchive/archive_read_support_format_ar.c b/libarchive/archive_read_support_format_ar.c
index 8873101..a832537 100644
--- a/libarchive/archive_read_support_format_ar.c
+++ b/libarchive/archive_read_support_format_ar.c
@@ -292,7 +292,7 @@ _ar_read_header(struct archive_read *a, struct archive_entry *entry,
 		}

 		/* Read the filename table into memory. */
-		st = malloc(strtab_size);
+		st = malloc(strtab_size + 1);
 		if (st == NULL) {
 			archive_set_error(&a->archive, ENOMEM,
 			    "Can't allocate filename table buffer");
@@ -301,6 +301,10 @@ _ar_read_header(struct archive_read *a, struct archive_entry *entry,
 		ar->strtab = st;
 		ar->strtab_size = strtab_size;

+		/* Always NUL-terminate the table.  Don't rely on the
+		 * last entry of the table being properly terminated. */
+		st[strtab_size] = '\0';
+
 		if (*unconsumed) {
 			__archive_read_consume(a, *unconsumed);
 			*unconsumed = 0;
@@ -327,7 +331,7 @@ _ar_read_header(struct archive_read *a, struct archive_entry *entry,
 	if (filename[0] == '/' && filename[1] >= '0' && filename[1] <= '9') {
 		number = ar_atol10(h + AR_name_offset + 1, AR_name_size - 1);
 		/* Fail if we can't look up the real name. */
-		if (ar->strtab == NULL || number >= ar->strtab_size) {
+		if (ar->strtab == NULL || number > ar->strtab_size) {
 			archive_set_error(&a->archive, EINVAL,
 			    "Can't find long filename for GNU/SVR4 archive entry");
 			return (ARCHIVE_FATAL);

